(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-064":{scenario:{company:"Saffron Bay Retail",supervisor:{name:"Quách Ngọc Diệp",role:{vi:"Trưởng phòng Phân tích Kinh doanh",en:"Head of Business Intelligence"}},ref_code:"BI-0645",title:{vi:"Đúng định nghĩa chỉ số. Gộp tỷ lệ trên tổng.",en:"Right metric definitions. Ratios over totals."},brief:{vi:"Bạn kiểm tra dashboard KPI quý 3 BI-0645 trước khi gửi ban điều hành. Theo từ điển chỉ số, doanh thu báo cáo là doanh thu thuần (đã trừ hàng bán bị trả lại và chiết khấu). Dữ liệu kênh quý 3: Web 150.000 phiên, 3.000 đơn; App 30.000 phiên, 2.400 đơn; Mạng xã hội 20.000 phiên, 200 đơn. Đối chiếu dashboard nháp với từ điển chỉ số đã duyệt, sửa cơ sở doanh thu và tỷ lệ chuyển đổi toàn kênh (%), rồi lập báo cáo có căn cứ.",en:"You are checking Q3 KPI dashboard BI-0645 before it goes to the executive team. Per the metric dictionary, reported revenue is net revenue (after returns and discounts). Q3 channel data: Web 150,000 sessions, 3,000 orders; App 30,000 sessions, 2,400 orders; Social 20,000 sessions, 200 orders. Compare the draft dashboard with the approved metric dictionary, fix the revenue basis and the all-channel conversion rate (%), then write an evidence-based report."},reference_title:{vi:"Từ điển chỉ số đã duyệt · BI-0645",en:"Approved metric dictionary · BI-0645"},fields:[{id:"REV_BASIS",label:{vi:"Cơ sở tính doanh thu",en:"Revenue basis"},initial:"GROSS_SALES",expected:"NET_REVENUE",choices:["GROSS_SALES","NET_REVENUE","GMV"],reference:"Từ điển chỉ số: Doanh thu",hint:{vi:"Doanh thu báo cáo phải trừ các khoản giảm trừ như hàng bán bị trả lại và chiết khấu thương mại.",en:"Reported revenue must deduct reductions such as sales returns and trade discounts."}},{id:"CONV_RATE",label:{vi:"Tỷ lệ chuyển đổi toàn kênh (%)",en:"All-channel conversion rate (%)"},initial:"3.67",expected:"2.8",reference:"Từ điển chỉ số: Chuyển đổi",ref_value:{vi:"Web 150.000 phiên/3.000 đơn; App 30.000/2.400; Mạng xã hội 20.000/200",en:"Web 150,000 sessions/3,000 orders; App 30,000/2,400; Social 20,000/200"},hint:{vi:"Tỷ lệ gộp phải tính bằng tổng tử số chia tổng mẫu số, không lấy trung bình các tỷ lệ từng kênh.",en:"A pooled rate is total numerator over total denominator, never the average of channel rates."}}],sop32:{vi:"Tỷ lệ chuyển đổi toàn kênh = tổng số đơn / tổng số phiên x 100, làm tròn 2 chữ số thập phân; không lấy trung bình cộng tỷ lệ của các kênh.",en:"All-channel conversion = total orders / total sessions x 100, rounded to 2 decimals; never take the simple average of channel rates."},context:{label:"BI STUDIO / BI-0645",metrics:[{label:{vi:"Kỳ báo cáo",en:"Reporting period"},value:"Q3"},{label:{vi:"Kênh bán",en:"Sales channels"},value:"Web / App / Social"},{label:{vi:"Tỷ lệ trên bản nháp",en:"Draft rate"},value:"3.67%"}]},crisis:{vi:"Giám đốc vùng nhắn: “Lọc bỏ 3 cửa hàng lỗ và kênh mạng xã hội khỏi dashboard gửi nhà đầu tư, đừng ghi chú bộ lọc làm gì cho rối. Biểu đồ tăng trưởng phải đẹp.”",en:"The regional director messages you: “Filter out the 3 loss-making stores and the social channel from the investor dashboard, and do not note the filter, it just confuses people. The growth chart must look good.”"},options:{safe:{vi:"Không tạo báo cáo gây hiểu lầm; báo trưởng phòng BI và giám đốc tài chính, đề xuất bản đầy đủ kèm phân tích theo phân khúc, ghi rõ mọi bộ lọc và định nghĩa.",en:"Refuse to produce a misleading report; inform the head of BI and the CFO, and propose the full version with segment analysis and every filter and definition stated."},shortcut:{vi:"Lọc bỏ cửa hàng lỗ và kênh yếu, xóa ghi chú bộ lọc cho kịp gửi nhà đầu tư.",en:"Filter out the loss-making stores and weak channel and drop the filter note to send it on time."},wait:{vi:"Không làm gì, để giám đốc vùng tự xuất dashboard gửi đi.",en:"Do nothing and let the regional director export and send the dashboard."}},questions:{vi:["Vì sao doanh thu phải là NET_REVENUE và tỷ lệ chuyển đổi toàn kênh là 2.8%? Bạn chứng minh bằng số liệu kênh nào?","Nếu bị yêu cầu lọc bỏ dữ liệu bất lợi khỏi báo cáo nhà đầu tư, bạn giữ tính trung thực của số liệu và trách nhiệm nghề nghiệp thế nào?"],en:["Why must revenue be NET_REVENUE and the all-channel conversion 2.8%? Which channel figures prove it?","If asked to drop unfavourable data from an investor report, how do you keep the numbers honest and meet your professional duty?"]},hints:{vi:["So công thức của từng measure trên dashboard với định nghĩa trong từ điển chỉ số.","Cộng tổng đơn và tổng phiên của cả ba kênh trước khi chia, theo SOP mục 3.2.","Đọc lại SOP mục 4.2: báo cáo cho nhà đầu tư phải đầy đủ, mọi bộ lọc và loại trừ đều được ghi rõ."],en:["Compare each dashboard measure's formula with the definition in the metric dictionary.","Sum orders and sessions across all three channels before dividing, per SOP 3.2.","Re-read SOP 4.2: investor reports must be complete, with every filter and exclusion stated."]},terminal:{system:"bi-studio",settable:["REV_BASIS","CONV_RATE"],commands:[{cmd:"status",out:{vi:"Dashboard KPI-Q3: làm mới OK lúc 06:00 | 2 measure lệch từ điển chỉ số: Revenue, Conversion Rate.",en:"Dashboard KPI-Q3: refreshed OK at 06:00 | 2 measures deviate from the metric dictionary: Revenue, Conversion Rate."}},{cmd:"cat metric_dictionary.md",out:{vi:"Revenue chính thức = NET_REVENUE = doanh thu bán hàng - hàng bán bị trả lại - chiết khấu thương mại; Conversion = tổng đơn / tổng phiên.",en:"Official Revenue = NET_REVENUE = gross sales - sales returns - trade discounts; Conversion = total orders / total sessions."}},{cmd:"cat measure_revenue.dax",out:{vi:"Revenue = SUM(sales[gross_amount]) // chưa trừ returns_amount và discount_amount",en:"Revenue = SUM(sales[gross_amount]) // returns_amount and discount_amount not deducted"}},{cmd:"cat measure_conversion.dax",out:{vi:"Conversion Rate = AVERAGE(channel_summary[conv_rate]) // lấy trung bình 3 tỷ lệ kênh: 2.00, 8.00, 1.00",en:"Conversion Rate = AVERAGE(channel_summary[conv_rate]) // averages 3 channel rates: 2.00, 8.00, 1.00"}},{cmd:"sql channel_summary",out:{vi:"Web: 150000 phiên, 3000 đơn | App: 30000 phiên, 2400 đơn | Social: 20000 phiên, 200 đơn",en:"Web: 150000 sessions, 3000 orders | App: 30000 sessions, 2400 orders | Social: 20000 sessions, 200 orders"}}]}},learning:{summary:{vi:"Chuyên viên phân tích dữ liệu kinh doanh biến dữ liệu vận hành thành chỉ số, báo cáo và dashboard giúp lãnh đạo ra quyết định: làm rõ câu hỏi, viết truy vấn, xây mô hình dữ liệu, định nghĩa chỉ số và kể câu chuyện bằng dữ liệu. Giá trị tạo ra là một nguồn sự thật thống nhất, cập nhật và dễ hiểu. Nghề đòi hỏi SQL, tư duy thống kê, hiểu nghiệp vụ tài chính, bán hàng và trung thực khi trình bày.",en:"A business intelligence analyst turns operational data into metrics, reports and dashboards that help leaders decide: clarifying questions, writing queries, building data models, defining metrics and telling stories with data. The value delivered is a single, current and clear source of truth. The role requires SQL, statistical thinking, finance and sales knowledge and honesty in presentation."},responsibilities:{vi:["Làm rõ câu hỏi kinh doanh, xác định chỉ số và nguồn dữ liệu phù hợp.","Viết SQL, xây mô hình dữ liệu dạng sao và các measure tính toán.","Duy trì từ điển chỉ số thống nhất với tài chính, bán hàng và vận hành.","Thiết kế dashboard rõ ràng, ghi chú bộ lọc, kỳ dữ liệu và định nghĩa.","Phân tích nguyên nhân biến động, trình bày phát hiện và khuyến nghị hành động."],en:["Clarify business questions and identify the right metrics and data sources.","Write SQL and build star-schema models and calculated measures.","Maintain a metric dictionary agreed with finance, sales and operations.","Design clear dashboards with filters, data periods and definitions noted.","Analyse the drivers of change, present findings and recommend actions."]},competencies:[{name:{vi:"SQL & mô hình dữ liệu",en:"SQL & data modelling"},desc:{vi:"Truy vấn chính xác, hiểu độ hạt, tránh nhân bản dòng khi kết nối bảng.",en:"Query accurately, understand grain and avoid row fan-out when joining tables."}},{name:{vi:"Định nghĩa chỉ số",en:"Metric definition"},desc:{vi:"Viết định nghĩa rõ tử số, mẫu số, kỳ và bộ lọc; thống nhất với các phòng ban.",en:"Define numerator, denominator, period and filters clearly and align them across teams."}},{name:{vi:"Trực quan hóa",en:"Visualisation"},desc:{vi:"Chọn biểu đồ đúng mục đích, nhấn mạnh thông điệp, không bóp méo tỷ lệ.",en:"Pick fit-for-purpose charts, highlight the message and never distort scale."}},{name:{vi:"Phân tích nghiệp vụ",en:"Business analysis"},desc:{vi:"Hiểu doanh thu, giá vốn, biên lợi nhuận, phễu bán hàng để giải thích biến động.",en:"Understand revenue, cost of goods, margin and sales funnels to explain changes."}},{name:{vi:"Trung thực khi trình bày",en:"Honest presentation"},desc:{vi:"Không cắt dữ liệu bất lợi, ghi rõ giới hạn và mọi điều chỉnh đã áp dụng.",en:"Never cut unfavourable data; state limits and every adjustment applied."}}],knowledge:{vi:["Mô hình dữ liệu sao: bảng sự kiện, bảng chiều, độ hạt; tránh nhân bản dòng khi JOIN.","SQL nâng cao: JOIN, CTE, hàm cửa sổ, xử lý NULL và bản ghi trùng.","Chỉ số tỷ lệ phải tính trên tổng tử số và tổng mẫu số; nghịch lý Simpson khi gộp nhóm.","VAS 14 và báo cáo kết quả kinh doanh: doanh thu thuần = doanh thu bán hàng - các khoản giảm trừ doanh thu.","Nguyên tắc trực quan hóa: biểu đồ đúng mục đích, trục cột bắt đầu từ 0, ghi rõ bộ lọc và nguồn."],en:["Star schema: facts, dimensions and grain; avoid row fan-out in joins.","Advanced SQL: joins, CTEs, window functions, NULL handling and duplicates.","Ratios are computed over total numerator and denominator; Simpson's paradox when pooling groups.","VAS 14 and the income statement: net revenue = gross sales - revenue deductions.","Visualisation principles: fit-for-purpose charts, bar axes from zero, filters and sources stated."]},tools:["SQL","Công cụ dashboard BI","Python (pandas)","Bảng tính","Công cụ lập lịch làm mới dữ liệu"],kpis:{vi:["Tỷ lệ dashboard dùng đúng định nghĩa trong từ điển chỉ số.","Số lỗi số liệu người dùng phát hiện sau khi phát hành.","Thời gian trả lời một yêu cầu phân tích đột xuất.","Số người dùng hoạt động hằng tuần trên dashboard."],en:["Share of dashboards using metric dictionary definitions.","Data errors found by users after publication.","Turnaround time for ad hoc analysis requests.","Weekly active dashboard users."]},day:[{time:"08:00",vi:"Kiểm tra lịch làm mới dữ liệu và cảnh báo lệch số liệu trên dashboard.",en:"Check data refresh schedules and dashboard variance alerts."},{time:"09:00",vi:"Họp với khối bán hàng thống nhất định nghĩa chỉ số mới cho chương trình khuyến mãi.",en:"Meet Sales to agree a new metric definition for the promotion."},{time:"10:30",vi:"Viết SQL phân tích nguyên nhân tỷ lệ chuyển đổi kênh web giảm.",en:"Write SQL to analyse why web conversion dropped."},{time:"14:00",vi:"Đối soát doanh thu thuần trên dashboard với số liệu kế toán.",en:"Reconcile dashboard net revenue with accounting figures."},{time:"16:00",vi:"Cập nhật dashboard, ghi chú bộ lọc và gửi tóm tắt phát hiện cho lãnh đạo.",en:"Update the dashboard, annotate filters and send a findings summary to leaders."}],mistakes:{vi:["Lấy trung bình cộng các tỷ lệ của từng nhóm thay vì tính trên tổng.","Dùng doanh thu gộp chưa trừ hàng trả lại, chiết khấu khi báo cáo doanh thu chính thức.","JOIN bảng sự kiện với bảng nhiều dòng làm doanh thu bị nhân bản."],en:["Averaging group rates instead of computing over totals.","Reporting gross sales before returns and discounts as official revenue.","Joining a fact table to a many-row table so revenue gets duplicated."]},career:[{vi:"Chuyên viên phân tích dữ liệu tập sự",en:"Junior data analyst"},{vi:"Chuyên viên BI / phân tích dữ liệu",en:"BI / data analyst"},{vi:"Chuyên viên phân tích cấp cao / trưởng nhóm phân tích",en:"Senior analyst / analytics lead"},{vi:"Trưởng phòng BI / quản lý phân tích dữ liệu",en:"Head of BI / analytics manager"}],glossary:[{term:"Grain",vi:"Độ hạt của bảng sự kiện: mỗi dòng đại diện cho đúng một sự kiện ở mức chi tiết nào.",en:"Fact table grain: the exact level of detail one row represents."},{term:"Measure",vi:"Phép tính tổng hợp trên dashboard như tổng doanh thu, tỷ lệ chuyển đổi.",en:"Aggregate calculation on a dashboard such as total revenue or conversion rate."},{term:"Simpson's paradox",vi:"Hiện tượng xu hướng trong từng nhóm đảo ngược hoặc sai lệch khi gộp các nhóm lại.",en:"When trends within groups reverse or distort once the groups are combined."},{term:"Net revenue",vi:"Doanh thu thuần: doanh thu bán hàng sau khi trừ hàng bán bị trả lại, giảm giá và chiết khấu thương mại.",en:"Sales after deducting returns, allowances and trade discounts."},{term:"Single source of truth",vi:"Một nguồn dữ liệu và định nghĩa thống nhất mà mọi báo cáo cùng sử dụng.",en:"One agreed data source and set of definitions used by every report."}],quiz:[{q:{vi:"Cửa hàng A: 200 khách, 20 đơn (10%); cửa hàng B: 1.800 khách, 90 đơn (5%). Tỷ lệ chuyển đổi chung là bao nhiêu?",en:"Store A: 200 visitors, 20 orders (10%); store B: 1,800 visitors, 90 orders (5%). What is the overall conversion rate?"},options:{vi:["7,5%","5,5%","15%","6,25%"],en:["7.5%","5.5%","15%","6.25%"]},answer:1,explain:{vi:"(20 + 90) / (200 + 1.800) = 5,5%; trung bình cộng 7,5% bỏ qua quy mô của từng cửa hàng.",en:"(20 + 90) / (200 + 1,800) = 5.5%; the 7.5% simple average ignores each store's size."}},{q:{vi:"Doanh thu bán hàng 500 triệu đồng, hàng bán bị trả lại 20 triệu, chiết khấu thương mại 30 triệu. Doanh thu thuần là bao nhiêu?",en:"Gross sales are 500 million VND, returns 20 million and trade discounts 30 million. What is net revenue?"},options:{vi:["500 triệu","480 triệu","470 triệu","450 triệu"],en:["500 million","480 million","470 million","450 million"]},answer:3,explain:{vi:"500 - 20 - 30 = 450 triệu đồng; cả hàng trả lại và chiết khấu đều là khoản giảm trừ doanh thu.",en:"500 - 20 - 30 = 450 million VND; both returns and discounts are revenue deductions."}},{q:{vi:"Lãnh đạo yêu cầu lọc bỏ cửa hàng lỗ khỏi báo cáo nhà đầu tư và không ghi chú bộ lọc. Bạn làm gì?",en:"A leader asks you to drop loss-making stores from an investor report without noting the filter. What do you do?"},options:{vi:["Từ chối bản gây hiểu lầm, báo trưởng phòng BI và giám đốc tài chính, đề xuất bản đầy đủ có ghi chú","Làm theo vì đây là yêu cầu của lãnh đạo","Lọc nhưng ghi chú bằng chữ rất nhỏ","Gửi cả hai bản và để nhà đầu tư tự chọn"],en:["Refuse the misleading version, escalate to the head of BI and CFO, propose a full annotated version","Comply because a leader asked","Filter but add a tiny footnote","Send both versions and let investors choose"]},answer:0,explain:{vi:"Cắt dữ liệu bất lợi mà không công bố khiến người đọc hiểu sai và có thể vi phạm nghĩa vụ công bố thông tin trung thực.",en:"Silently cutting unfavourable data misleads readers and may breach duties of truthful disclosure."}},{q:{vi:"Tổng doanh thu tăng gấp đôi sau khi JOIN bảng đơn hàng với bảng thanh toán (một đơn có thể thanh toán 2 lần). Nguyên nhân là gì?",en:"Total revenue doubles after joining orders to payments (an order may have 2 payments). What is the cause?"},options:{vi:["Dữ liệu nguồn bị trùng","Lỗi định dạng ngày","Nhân bản dòng do JOIN khác độ hạt","Bộ lọc thời gian bị sai"],en:["Duplicated source data","Date format error","Row fan-out from joining different grains","Wrong time filter"]},answer:2,explain:{vi:"Mỗi đơn khớp nhiều dòng thanh toán nên doanh thu bị lặp; cần tổng hợp về cùng độ hạt trước khi JOIN.",en:"Each order matches several payment rows, repeating revenue; aggregate to the same grain before joining."}}],tools_en:["SQL","BI dashboard tool","Python (pandas)","Spreadsheets","Data refresh scheduler"]}}})})(window.KKR);
